text:
{
  "design": {
    "theme": "chalk",
    "picture_style": "illustration"
  },
  "flow": [
    {"slide": 1, "does": "Recall avoir, numbers and personal introductions", "look_at": {"kind": "none", "shows": null}, "teaches": []},
    {"slide": 2, "does": "Introduce the approved learning objectives", "look_at": {"kind": "none", "shows": null}, "teaches": []},
    {"slide": 3, "does": "Teach family nouns and possessive forms", "look_at": {"kind": "diagram", "shows": "Six French family expressions with English meanings"}, "teaches": [1]},
    {"slide": 4, "does": "Correct the belief that mon or ma depends on the speaker", "look_at": {"kind": "picture", "shows": "A girl and a boy each standing beside their mother"}, "teaches": [1]},
    {"slide": 5, "does": "Check selection of possessives", "look_at": {"kind": "none", "shows": null}, "teaches": [1]},
    {"slide": 6, "does": "Teach pronouns and adjective agreement", "look_at": {"kind": "picture", "shows": "Male and female family members doing friendly or amusing things"}, "teaches": [2]},
    {"slide": 7, "does": "Model a name, age and personality description", "look_at": {"kind": "picture", "shows": "An imaginary sister"}, "teaches": [2]},
    {"slide": 8, "does": "Practise a closely matched description", "look_at": {"kind": "none", "shows": null}, "teaches": [2]},
    {"slide": 9, "does": "Model sibling statements and a complete paragraph", "look_at": {"kind": "none", "shows": null}, "teaches": [3]},
    {"slide": 10, "does": "Practise a closely matched family paragraph", "look_at": {"kind": "none", "shows": null}, "teaches": [1, 2, 3]},
    {"slide": 11, "does": "Apply grammar by repairing a new description", "look_at": {"kind": "none", "shows": null}, "teaches": [1, 2, 3]},
    {"slide": 12, "does": "Write independently and complete the worksheet exit ticket", "look_at": {"kind": "none", "shows": null}, "teaches": [1, 2, 3]}
  ],
  "title": {
    "template": "title",
    "heading": "Ma famille",
    "lead": "Rappelle-toi / Recall:\nHow do you say “I have”, “I am” and “My name is”?\nSay 12 and 14 in French.",
    "picture": null
  },
  "slides": [
    {
      "template": "visual-text",
      "heading": "Les membres de ma famille",
      "lead": "Mon / ma / mes = my. Choose to match the French noun.",
      "points": [
        {"label": "mon", "text": "Masculine singular"},
        {"label": "ma / mes", "text": "ma: feminine singular; mes: plural"}
      ],
      "figure": {
        "kind": "table",
        "shows": "French family vocabulary and its English meaning",
        "alt": "Six family expressions paired with their English meanings.",
        "title": null,
        "header": ["Français", "English"],
        "rows": [
          ["mon père", "father"],
          ["ma mère", "mother"],
          ["mon frère", "brother"],
          ["ma sœur", "sister"],
          ["mes parents", "parents"],
          ["mes grands-parents", "grandparents"]
        ]
      }
    },
    {
      "template": "visual-text",
      "heading": "Mon ou ma : qui décide ?",
      "lead": "Both children say « ma mère ». The noun mère is feminine, whoever is speaking.",
      "points": [
        "A girl says « mon père » too.",
        "Match the noun, not the speaker."
      ],
      "figure": {
        "shows": "Two separate scenes: a girl beside her mother and a boy beside his mother",
        "must_see": ["girl beside mother", "boy beside mother"],
        "subject": "generic"
      }
    },
    {
      "template": "hinge",
      "heading": "Choisis la bonne réponse",
      "stem": "A girl says “my father, my mother, my parents”. Which is correct?",
      "options": [
        "ma père, ma mère, ma parents",
        "mon père, ma mère, mes parents",
        "mon père, mon mère, mes parents",
        "mes père, mes mère, mes parents"
      ],
      "correct": 2
    },
    {
      "template": "compare",
      "heading": "Il est… / Elle est…",
      "columns": [
        {
          "label": "Il = he",
          "text": "Il est gentil. — kind\nIl est amusant. — funny",
          "picture": {
            "shows": "An imaginary brother helping someone carry shopping while making them laugh",
            "must_see": ["teenage boy", "shopping bags", "smiling faces"],
            "subject": "generic"
          }
        },
        {
          "label": "Elle = she",
          "text": "Elle est gentille. — kind\nElle est amusante. — funny",
          "picture": {
            "shows": "An imaginary sister helping someone carry shopping while making them laugh",
            "must_see": ["teenage girl", "shopping bags", "smiling faces"],
            "subject": "generic"
          }
        }
      ]
    },
    {
      "template": "steps",
      "heading": "Décrire ma sœur / Describe my sister",
      "points": [
        "Elle s’appelle Léa. — Her name is Léa.",
        "Elle a douze ans. — She is twelve.",
        "Elle est gentille. — She is kind."
      ],
      "figure": {
        "shows": "An imaginary young teenage sister smiling",
        "must_see": ["young teenage girl", "friendly smile"],
        "subject": "generic"
      }
    },
    {
      "template": "practice",
      "heading": "À toi / Your turn",
      "questions": [
        "My sister is called Emma. Write her name sentence.",
        "She is fourteen. Write her age sentence. fourteen = quatorze",
        "She is funny. Write her personality sentence. funny = amusant / amusante"
      ],
      "instruction": "Écris trois phrases. / Write three sentences.",
      "picture": null
    },
    {
      "template": "explain",
      "heading": "J’ai… / Je n’ai pas de…",
      "lead": "J’ai un frère. Je n’ai pas de sœur. Mon frère s’appelle Hugo. Il a quinze ans. Il est amusant.",
      "points": [
        {"label": "J’ai", "text": "I have: un frère / une sœur."},
        {"label": "Je n’ai pas de", "text": "I don’t have: de frère / de sœur."}
      ]
    },
    {
      "template": "practice",
      "heading": "Une famille imaginaire",
      "questions": [
        "You have a brother but no sister. Write both sibling statements.",
        "Your brother is called Louis and is sixteen. Write his name and age. sixteen = seize",
        "He is kind. Add his personality. kind = gentil / gentille"
      ],
      "instruction": "Écris un paragraphe. / Write one paragraph.",
      "picture": null
    },
    {
      "template": "practice",
      "heading": "Répare le message / Repair the message",
      "questions": [
        "“ma frère” means “my brother”. Correct the French.",
        "“Il est gentille.” means “He is kind.” Correct the French.",
        "“Je n’ai pas un sœur.” means “I have no sister.” Correct the French."
      ],
      "instruction": "Corrige et explique. / Correct each phrase and explain why.",
      "picture": null
    },
    {
      "template": "practice",
      "heading": "Présente ta famille",
      "questions": [
        "Write about your own or an imaginary family: say which siblings you have and do not have.",
        "Describe one family member: relationship, name, age and one personality trait.",
        "Défi / Stretch: describe a second family member of a different gender."
      ],
      "instruction": "Écris 5–7 phrases. / Write 5–7 sentences. Check mon / ma / mes, il / elle and adjective endings.",
      "picture": null
    }
  ]
}
